#include <stdlib.h>
#include <string.h>

struct xt_table_info {
    unsigned int size;
    // Assume other fields are defined here
};

struct xt_table_info* allocate_xt_table_info(unsigned int size) {
    struct xt_table_info* table_info = NULL;
    size_t total_size = sizeof(struct xt_table_info);

    // Check for overflow in size calculation
    if (size > (SIZE_MAX - sizeof(struct xt_table_info)) / sizeof(unsigned int)) {
        return NULL;
    }

    total_size += size * sizeof(unsigned int);

    // Try to allocate memory using kmalloc equivalent (malloc in C)
    table_info = (struct xt_table_info*)malloc(total_size);

    // If kmalloc fails, try vmalloc equivalent (malloc in C)
    if (table_info == NULL) {
        table_info = (struct xt_table_info*)malloc(total_size);
    }

    // If allocation failed, return NULL
    if (table_info == NULL) {
        return NULL;
    }

    // Zero out the allocated memory
    memset(table_info, 0, total_size);

    // Set the size in the structure
    table_info->size = size;

    return table_info;
}
